import os, glob, docx, openpyxl
base='/filesystem/Birchwood/PackageA'
for root, dirs, files in os.walk(base):
    for fn in files:
        p=os.path.join(root,fn)
        rel=os.path.relpath(p,base).replace('/','__')
        if fn.endswith('.docx'):
            d=docx.Document(p)
            txt='\n'.join(par.text for par in d.paragraphs)
            for t in d.tables:
                for r in t.rows:
                    txt+='\n'+' || '.join(c.text for c in r.cells)
            open(f'/tmp/txt/{rel}.txt','w').write(txt)
        elif fn.endswith('.xlsx'):
            wb=openpyxl.load_workbook(p)
            lines=[]
            for ws in wb.worksheets:
                lines.append(f'=== SHEET {ws.title}')
                for row in ws.iter_rows():
                    vals=[f'{c.coordinate}={c.value!r}' for c in row if c.value is not None]
                    if vals: lines.append(' | '.join(vals))
            open(f'/tmp/txt/{rel}.txt','w').write('\n'.join(lines))
        elif fn.endswith('.eml'):
            open(f'/tmp/txt/{rel}.txt','w').write(open(p).read())
EOF
