import docx
from docx.shared import Pt
d = docx.Document('Thelbridge_Materials_Acceptance_Record_TEMPLATE.docx')
sec = d.sections[0]
print("Page:", sec.page_width, sec.page_height, "margins", sec.left_margin, sec.right_margin, sec.top_margin, sec.bottom_margin)
print("Header paras:", [p.text for p in sec.header.paragraphs], "Header tables:", len(sec.header.tables))
for t in sec.header.tables:
    for r in t.rows: print("  H|", " || ".join(c.text for c in r.cells))
print("Footer paras:", [p.text for p in sec.footer.paragraphs])
for t in sec.footer.tables:
    for r in t.rows: print("  F|", " || ".join(c.text for c in r.cells))
print("=== BODY (in order) ===")
from docx.oxml.ns import qn
body = d.element.body
ti=0; pi=0
for child in body.iterchildren():
    tag = child.tag.split('}')[1]
    if tag == 'p':
        p = d.paragraphs[pi]; pi+=1
        runs = [(r.text, r.bold, r.italic, r.font.size, r.font.name) for r in p.runs]
        print(f"P[{pi-1}] style={p.style.name!r} align={p.alignment} text={p.text!r}")
        if p.text.strip():
            print("     runs:", runs)
    elif tag == 'tbl':
        t = d.tables[ti]; ti+=1
        print(f"TABLE[{ti-1}] style={t.style.name if t.style else None} rows={len(t.rows)} cols={len(t.columns)}")
        for ri, r in enumerate(t.rows):
            print(f"   R{ri}:", " || ".join(repr(c.text) for c in r.cells))
    elif tag == 'sectPr':
        print("sectPr")
